import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"职位与权限","description":"","frontmatter":{},"headers":[],"relativePath":"towns/Roles.md","filePath":"towns/Roles.md"}'),n={name:"towns/Roles.md"};function r(c,t,i,l,s,u){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="职位与权限" tabindex="-1">职位与权限 <a class="header-anchor" href="#职位与权限" aria-label="Permalink to &quot;职位与权限&quot;">​</a></h1><p>联盟的权限体系分为两层：<strong>联盟职位权限</strong>（成员在联盟内能做什么）与<strong>领地旗标权限</strong>（在联盟领地里能做什么）。</p><h2 id="联盟职位" tabindex="-1">联盟职位 <a class="header-anchor" href="#联盟职位" aria-label="Permalink to &quot;联盟职位&quot;">​</a></h2><p>每个联盟拥有若干职位（权限组），新联盟默认有两个：</p><ul><li><strong>盟主</strong>：拥有全部权限，可管理联盟的一切。</li><li><strong>成员</strong>：基础权限。</li></ul><h3 id="职位管理-盟主专属" tabindex="-1">职位管理（盟主专属） <a class="header-anchor" href="#职位管理-盟主专属" aria-label="Permalink to &quot;职位管理（盟主专属）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/union rank list</code></td><td>查看所有职位</td></tr><tr><td><code>/union rank create &lt;职位ID&gt; &lt;等级&gt; [名称]</code></td><td>创建职位（等级决定权限高低）</td></tr><tr><td><code>/union rank delete &lt;职位ID&gt;</code></td><td>删除职位</td></tr><tr><td><code>/union rank setperm &lt;职位ID&gt; &lt;权限&gt; &lt;on|off&gt;</code></td><td>开关职位权限</td></tr><tr><td><code>/union rank set &lt;玩家&gt; &lt;职位ID&gt;</code></td><td>调整成员职位</td></tr></tbody></table><blockquote><p>等级越高的职位权限越大；只能把成员分配到<strong>等级低于自己职位</strong>的组。</p></blockquote><h3 id="联盟权限一览" tabindex="-1">联盟权限一览 <a class="header-anchor" href="#联盟权限一览" aria-label="Permalink to &quot;联盟权限一览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>union.rank.assign.N</code></td><td>分配等级 N 以下的职位（N 不高于自身级别）</td></tr><tr><td><code>union.member.invite</code></td><td>邀请成员</td></tr><tr><td><code>union.member.kick</code></td><td>踢出成员</td></tr><tr><td><code>union.member.audit</code></td><td>审核入盟申请</td></tr><tr><td><code>union.account.deposit</code></td><td>向联盟账户存款</td></tr><tr><td><code>union.account.withdraw</code></td><td>联盟账户取款/拨款</td></tr><tr><td><code>union.account.give</code></td><td>把联盟资金分配给成员</td></tr><tr><td><code>union.account.log</code></td><td>查看联盟账户流水</td></tr><tr><td><code>union.config-edit</code></td><td>修改联盟配置</td></tr><tr><td><code>union.pvp.attackAlly</code></td><td>允许攻击盟友</td></tr><tr><td><code>union.pvp.attackedByAlly</code></td><td>允许被盟友攻击</td></tr></tbody></table><p><strong>盟主专属权限</strong>（不可分配给其他职位）：解散联盟（<code>union.leader.disband</code>）、转让盟主（<code>union.leader.transfer</code>）、编辑职位定义（<code>union.leader.rank-edit</code>）。</p><h2 id="领地联动权限" tabindex="-1">领地联动权限 <a class="header-anchor" href="#领地联动权限" aria-label="Permalink to &quot;领地联动权限&quot;">​</a></h2><p>联盟职位同时决定成员在<strong>联盟领地</strong>中的行为（由 PepperClaim 联动）：</p><table tabindex="0"><thead><tr><th>职位</th><th>默认拥有的领地权限</th></tr></thead><tbody><tr><td><strong>成员</strong></td><td><code>union.claim.build</code>（建造）、<code>union.claim.use</code>（使用物品）、<code>union.claim.container</code>（开箱）、<code>union.claim.move</code>（进入）、<code>union.claim.riding</code>（骑乘）、<code>union.claim.tp</code>（传送）</td></tr><tr><td><strong>盟主/管理职位</strong></td><td>在成员权限基础上增加：<code>union.claim.create</code>（创建领地）、<code>union.claim.manage</code>（管理领地）、<code>union.claim.flag</code>（设置旗标）、<code>union.claim.sub.create</code>（创建子领地）、<code>union.claim.sub.manage</code>（管理子领地）、<code>union.claim.buy</code>（购买额度）</td></tr></tbody></table><h2 id="领地旗标权限" tabindex="-1">领地旗标权限 <a class="header-anchor" href="#领地旗标权限" aria-label="Permalink to &quot;领地旗标权限&quot;">​</a></h2><p>联盟领地的精细保护用<strong>旗标</strong>控制，可按职位单独设置：</p><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/gclaim perms &lt;领地&gt;</code></td><td>查看职位权限</td></tr><tr><td><code>/gclaim perm &lt;领地&gt; &lt;职位&gt; &lt;旗标&gt; &lt;值&gt;</code></td><td>给某职位设置旗标（如 <code>build ALLOW</code>）</td></tr></tbody></table><p>常用旗标与取值见<a href="./Claims.html#旗标-细粒度保护">领地页面</a>。</p>',18)])])}const m=d(n,[["render",r]]);export{g as __pageData,m as default};
